    css['css-advanced-heading-spacing'] = '.rm-block--closed.rm-level1, .rm-block--closed.rm-heading-level-1 > .rm-block__self .rm-block__input, .rm-block--closed.rm-heading-level-1 > .rm-block__self > .controls, .rm-block--closed.rm-heading-level-1 > .rm-block__self > .rm-block__controls, .rm-block--closed.rm-level2, .rm-block--closed.rm-heading-level-2 > .rm-block__self .rm-block__input, .rm-block--closed.rm-heading-level-2 > .rm-block__self > .controls, .rm-block--closed.rm-heading-level-2 > .rm-block__self > .rm-block__controls, .rm-block--closed.rm-level3, .rm-block--closed.rm-heading-level-3 > .rm-block__self .rm-block__input, .rm-block--closed.rm-heading-level-3 > .rm-block__self > .controls, .rm-block--closed.rm-heading-level-3 > .rm-block__self > .rm-block__controls {   margin-top: 0;   margin-bottom: 0; } ';
    css['css-bullet-effects'] = '.rm-bullet:hover .rm-bullet__inner {   width: 9px;   height: 9px;   border: 2px solid transparent;   transition: all 0.2s ease-in-out; }  .sidebar-content .rm-bullet.rm-bullet--closed:hover .rm-bullet__inner, .rm-bullet.rm-bullet--closed:hover .rm-bullet__inner {   border: 2px solid transparent; } ';
    css['css-centered-search'] = '@media (hover: hover) and (pointer: fine) {     .rm-find-or-create-wrapper[style="flex: 0 1 200px;"] {         position: absolute;         top: -80px;     }      .rm-find-or-create-wrapper[style="flex: 0 1 200px;"] input {         background-color: transparent;         padding-left: 20px !important;     }      .rm-help-popup {         z-index: 1001;     }      .rm-find-or-create-wrapper .bp3-menu {         max-height: 340px;     }      .roam-app .flex-h-box[style*="margin-left: 232px;"] .rm-find-or-create-wrapper:not([style*="flex: 0 1 200px"]) {         left: -232px;     }      .rm-find-or-create-wrapper:not([style*="flex: 0 1 200px"]) {         border-radius: 15px;         bottom: 0;         display: block;         height: 400px;         left: 0;         margin: auto;         max-width: 600px;         padding: 10px;         position: absolute;         right: 0;         top: 0;         width: 95%;         z-index: 1000;     }      .rm-find-or-create-wrapper .bp3-popover .bp3-popover-content {         background-color: transparent !important;         border: none;     }      .rm-find-or-create-wrapper .bp3-popover {         box-shadow: none !important;     }      .rm-find-or-create-wrapper .bp3-transition-container {         transform: translate3d(0px, 50px, 0px) !important;     }      .rm-find-or-create-wrapper {         transition: none;         box-shadow: var(--sd-dialog)!important;         border: var(--br-dialog)!important;     }      .rm-find-or-create-wrapper .bp3-menu {         padding: 10px;     }      .rm-find-or-create-wrapper {         background-color: var(--bc-find-or-create, #fafafa) !important;         border-radius: 6px;     }      @media (prefers-color-scheme: dark) {         .rm-find-or-create-wrapper {             background-color: var(--bc-find-or-create, #202020) !important;         }     }      .rm-find-or-create__menu,     .rm-find-or-create__menu .bp3-menu {         background-color: transparent !important;     }      .rm-find-or-create-wrapper[style="flex: 0 1 200px;"] .bp3-menu {         display: none;     }      .rm-find-or-create-wrapper .bp3-popover {         border: none;     } }';
    css['css-done'] = 'div:has(>span>span>span>span>span>span>label>input:checked), div:has(>span>span>label>input:checked) {   color: gray!important;   text-decoration: line-through; }';
    css['css-dynamic-images'] = '/* Images in the right sidebar will be scaled dynamically to fit the width of the bar.  Images in the content area will be scaled to 100% once the reach the max width of 580px */  #roam-right-sidebar-content .rm-inline-img__resize, #roam-right-sidebar-content .react-resizable { 	width: unset!important; }  .rm-inline-img__resize[style*="width: 580px"], .react-resizable[style*="width: 580px"] { 	width: 100%!important; }';
    css['css-dynamic-pdfs'] = 'div.hoverparent[style*="width: 580px;"], div.hoverparent[style*="width: 580px;"] div.react-resizable { 	width: 100% !important; }';
